function draw({svg,width,height,progress,params}) {
  const ns='http://www.w3.org/2000/svg';
  const nodes=svg.__nodes||(svg.__nodes=new Map()); const used=new Set();
  function el(key,tag,a,text){let n=nodes.get(key);if(!n){n=document.createElementNS(ns,tag);svg.appendChild(n);nodes.set(key,n);}used.add(key);for(const [k,v] of Object.entries(a))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;}
  function txt(key,x,y,value,attrs={}){return el(key,'text',{x,y,fill:'var(--ink)','font-size':13,'font-family':'system-ui, sans-serif','text-anchor':'middle',...attrs},value);}
  function line(key,x1,y1,x2,y2,attrs={}){return el(key,'line',{x1,y1,x2,y2,stroke:'var(--muted)','stroke-width':1,...attrs});}
  function path(key,d,attrs={}){return el(key,'path',{d,fill:'none',stroke:'var(--blue)','stroke-width':2,...attrs});}
  function dot(key,x,y,r,attrs={}){return el(key,'circle',{cx:x,cy:y,r,fill:'var(--blue)',...attrs});}
  const fmt=v=>Math.abs(v)<0.00001?'0':Number(v.toFixed(2)).toString();
  function finish(){for(const [k,n] of nodes){if(!used.has(k)){n.remove();nodes.delete(k);}}}

  const p=progress,axis=params.axis===1?1:0,delta=params.delta;
  const A=Array.from({length:5},(_,r)=>Array.from({length:4},(_,c)=>4*r+c+(r===0&&c===0?delta:0)));
  const sums=axis===0?A[0].map((_,c)=>A.reduce((s,row)=>s+row[c],0)):A.map(row=>row.reduce((s,v)=>s+v,0));
  const cw=width<450?38:42,x0=(width-(4*cw+90))/2+20,y0=79,rh=width<450?32:30;
  const dy=height-51,dx=x0+4*cw+56;
  txt('head',8,20,'A · (5,4)',{'text-anchor':'start','font-size':14});
  txt('resulthead',width-8,20,axis===0?'sum(0) · (4,)':'sum(1) · (5,)',{'text-anchor':'end','font-size':14});
  txt('colaxis',x0+2*cw,44,'轴1 →',{fill:'var(--muted)'});
  txt('rowaxis',x0-40,y0+77,'轴0 →',{fill:'var(--muted)',transform:`rotate(90 ${x0-40} ${y0+77})`});
  for(let c=0;c<4;c++)txt('col'+c,x0+(c+.5)*cw,64,c,{fill:'var(--muted)'});
  for(let r=0;r<5;r++)txt('row'+r,x0-13,y0+r*rh+21,r,{fill:'var(--muted)'});
  const terms=[];
  for(let r=0;r<5;r++)for(let c=0;c<4;c++){
    const k=r+'-'+c,sx=x0+(c+.5)*cw,sy=y0+(r+.5)*rh;
    const tx=axis===0?sx:dx,ty=axis===0?dy:sy;
    el('cell'+k,'rect',{x:sx-cw/2+2,y:sy-rh/2+2,width:cw-4,height:rh-4,fill:'none',stroke:'var(--muted)','stroke-opacity':.17,'stroke-width':1});
    const x=sx+(tx-sx)*p,y=sy+(ty-sy)*p;
    line('trail'+k,sx,sy,tx,ty,{stroke:'var(--blue)','stroke-opacity':.08});
    dot('dot'+k,x,y,3.5,{opacity:Math.min(1,p*5)*(1-p),'fill':axis===0?'var(--blue)':'var(--orange)'});
    txt('v'+k,x,y+4,fmt(A[r][c]),{opacity:Math.max(0,1-p/.46)});
    terms.push({value:A[r][c],row:r,column:c,x,y});
  }
  for(let g=0;g<sums.length;g++){
    const x=axis===0?x0+(g+.5)*cw:dx,y=axis===0?dy:y0+(g+.5)*rh;
    el('out'+g,'rect',{x:x-19,y:y-15,width:38,height:30,rx:2,fill:axis===0?'var(--blue)':'var(--orange)','fill-opacity':.07});
    txt('sum'+g,x,y+4,fmt(sums[g]),{opacity:.22+.78*p,'font-size':14});
  }
  txt('foot',width/2,height-10,axis===0?'行合并，列位置保留':'列合并，行位置保留',{fill:'var(--muted)'});
  finish();return {progress:p,axis,inputShape:[5,4],input:A,outputShape:[sums.length],sums,terms};
}

function draw({svg,width,height,progress,params}) {
  const ns='http://www.w3.org/2000/svg';
  const nodes=svg.__nodes||(svg.__nodes=new Map()); const used=new Set();
  function el(key,tag,a,text){let n=nodes.get(key);if(!n){n=document.createElementNS(ns,tag);svg.appendChild(n);nodes.set(key,n);}used.add(key);for(const [k,v] of Object.entries(a))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;}
  function txt(key,x,y,value,attrs={}){return el(key,'text',{x,y,fill:'var(--ink)','font-size':13,'font-family':'system-ui, sans-serif','text-anchor':'middle',...attrs},value);}
  function line(key,x1,y1,x2,y2,attrs={}){return el(key,'line',{x1,y1,x2,y2,stroke:'var(--muted)','stroke-width':1,...attrs});}
  function path(key,d,attrs={}){return el(key,'path',{d,fill:'none',stroke:'var(--blue)','stroke-width':2,...attrs});}
  function dot(key,x,y,r,attrs={}){return el(key,'circle',{cx:x,cy:y,r,fill:'var(--blue)',...attrs});}
  const fmt=v=>Math.abs(v)<0.00001?'0':Number(v.toFixed(2)).toString();
  function finish(){for(const [k,n] of nodes){if(!used.has(k)){n.remove();nodes.delete(k);}}}

  const p=progress,k=params.shear,q=p*k;
  const cx=width/2,cy=height/2+13,s=Math.min((width-80)/7,(height-100)/4.2);
  const X=x=>cx+x*s,Y=y=>cy-y*s;
  txt('matrix',8,21,'A(t) = [1, t·k; 0, 1]',{'text-anchor':'start','font-size':14});
  txt('t',width-8,21,'t = '+p.toFixed(2),{'text-anchor':'end'});
  const paths=[];
  for(let i=-2;i<=2;i++){
    line('ghostv'+i,X(i),Y(-1.5),X(i),Y(1.5),{'stroke-opacity':.12});
    line('ghosth'+i,X(-2),Y(i/2),X(2),Y(i/2),{'stroke-opacity':.12});
    const v=[[i-q*1.5,-1.5],[i+q*1.5,1.5]],h=[[-2+q*i/2,i/2],[2+q*i/2,i/2]];
    path('gridv'+i,`M${X(v[0][0])},${Y(v[0][1])}L${X(v[1][0])},${Y(v[1][1])}`,{'stroke-opacity':.2,'stroke-width':1});
    path('gridh'+i,`M${X(h[0][0])},${Y(h[0][1])}L${X(h[1][0])},${Y(h[1][1])}`,{'stroke-opacity':.2,'stroke-width':1});paths.push({vertical:v,horizontal:h});
  }
  line('axisx',X(-3),Y(0),X(3),Y(0),{'stroke-opacity':.65});
  line('axisy',X(0),Y(-1.9),X(0),Y(2),{'stroke-opacity':.65});
  txt('xaxis',X(3),Y(0)+42,'横坐标',{'text-anchor':'end',fill:'var(--muted)'});
  txt('yaxis',X(0)+10,Y(2)-8,'纵坐标',{'text-anchor':'start',fill:'var(--muted)'});
  for(const x of [-2,-1,1,2])txt('tickx'+x,X(x),Y(0)+17,x,{fill:'var(--muted)'});
  txt('zero',X(0)-10,Y(0)+17,'0',{fill:'var(--muted)'});
  txt('ticky',X(0)-12,Y(-1)+4,'−1',{fill:'var(--muted)','text-anchor':'end'});
  const x=[1,1],col1=[1,0],col2=[q,1],out=[1+q,1];
  path('input',`M${X(0)},${Y(0)}L${X(1)},${Y(1)}`,{stroke:'var(--muted)','stroke-dasharray':'4 4','stroke-opacity':.6});
  path('sum1',`M${X(0)},${Y(0)}L${X(1)},${Y(0)}`,{stroke:'var(--orange)','stroke-width':4});
  path('sum2',`M${X(1)},${Y(0)}L${X(out[0])},${Y(out[1])}`,{stroke:'var(--orange)','stroke-width':2,'stroke-dasharray':'4 3'});
  path('output',`M${X(0)},${Y(0)}L${X(out[0])},${Y(out[1])}`,{'stroke-width':3});
  dot('end',X(out[0]),Y(out[1]),5);
  txt('outlabel',X(out[0]),Y(out[1])-17,'A(t)x');
  txt('basis1',X(.5),Y(0)+39,'第1列',{fill:'var(--muted)'});
  txt('basis2',X((1+out[0])/2)+18,Y(.5)+4,'第2列',{'text-anchor':'start',fill:'var(--muted)'});
  txt('foot',width/2,height-13,'x = (1,1) → '+ '('+fmt(out[0])+', 1)',{'font-size':14});
  finish();return {progress:p,shear:k,matrix:[[1,q],[0,1]],input:x,columns:[col1,col2],output:out,grid:paths};
}

